{"content":"package cli

import (
	"errors"
	"reflect"
	"testing"
)

func mustParse(t *testing.T, args ...string) Config {
	t.Helper()
	c, err := Parse(args)
	if err != nil {
		t.Fatalf("Parse(%v) = %v", args, err)
	}
	return c
}

func TestAllRules(t *testing.T) {
	c := mustParse(t, "--verbose", "-n", "3", "--count=5", "-o", "a.txt", "-o=b.txt", "--tag", "x", "--tag=y", "pos", "--", "-v", "-")
	want := Config{Verbose: true, Count: 5, Output: "b.txt", Tags: []string{"x", "y"}, Args: []string{"pos", "-v", "-"}}
	if !reflect.DeepEqual(c, want) {
		t.Fatalf("got %+v want %+v", c, want)
	}

	if !mustParse(t, "-vv").Verbose {
		t.Fatal("-vv should be verbose")
	}
	if mustParse(t).Count != 1 {
		t.Fatal("default count")
	}
	if mustParse(t, "a", "b").Tags != nil || mustParse(t, "a", "b").Args == nil {
		t.Fatal("tags nil / args set")
	}
	if mustParse(t, "a").Args == nil {
		t.Fatal("args set for positional")
	}

	bad := [][]string{
		{"-n"},
		{"-n", "x"},
		{"-n", "-1"},
		{"--count", "abc"},
		{"--count=-2"},
		{"-z"},
		{"--nope"},
		{"--o"},
	}
	for _, a := range bad {
		_, err := Parse(a)
		if err == nil || !errors.Is(err, ErrUsage) {
			t.Fatalf("Parse(%v) err = %v, want ErrUsage", a, err)
		}
	}
}
